// ADR-0019 Decision 1 / ADR-0006 — signature is HMAC-SHA256 over
// `${timestamp}.${rawBody}`, using the EXACT bytes EYAN sent (not a
// re-serialization of the parsed JSON), captured via the Webhook node's
// "Raw Body" option as base64 in binary.data.data.
const item = $input.item;
const headers = item.json.headers || {};
const signatureHeader = String(headers['x-eyan-signature'] || '');
const timestampHeader = String(headers['x-eyan-timestamp'] || '');

const receivedSignature = signatureHeader.startsWith('sha256=')
  ? signatureHeader.slice(7)
  : signatureHeader;

const timestampMs = Number(timestampHeader);
const rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : '';

// 5-minute replay window — matches ADR-0019 Decision 1 / TDD §17.
const FRESHNESS_WINDOW_MS = 5 * 60 * 1000;
const isFresh = Number.isFinite(timestampMs) && Math.abs(Date.now() - timestampMs) <= FRESHNESS_WINDOW_MS;

return [{
  json: {
    hasSignature: signatureHeader.length > 0,
    receivedSignature,
    isFresh,
    rawBody,
    signedString: `${timestampHeader}.${rawBody}`,
  },
}];

// A plain string comparison (not crypto.timingSafeEqual) is a deliberate,
// documented simplification here — see docs/adrs/ADR-0006-crm-workflow-authentication.md
// for why this threat model differs from EYAN's own authenticateService
// comparison, and why n8n's Code node sandbox has no network/require access
// this workflow needs anyway (HMAC computation itself uses the native
// Crypto node + an encrypted credential, never $env or require('crypto')).
const prep = $('Prepare Verification Input').item.json;
const computed = $json.computedSignature;

if (!prep.hasSignature || computed !== prep.receivedSignature) {
  return [{ json: { valid: false, reason: 'Invalid signature.' } }];
}

if (!prep.isFresh) {
  return [{ json: { valid: false, reason: 'Stale timestamp (outside the 5 minute freshness window).' } }];
}

let payload;
try {
  payload = JSON.parse(prep.rawBody);
} catch (error) {
  return [{ json: { valid: false, reason: 'Malformed JSON body.' } }];
}

if (!payload || !payload.lead || !payload.lead.id) {
  return [{ json: { valid: false, reason: 'Missing lead payload.' } }];
}

return [{ json: { valid: true, lead: payload.lead, contractVersion: payload.contractVersion } }];

// $execution.id is n8n's own execution ID — reused as the ADR-0019
// idempotency key (workflowExecutionId) rather than minting a separate UUID,
// keeping this traceable directly in the n8n UI.
return [{ json: { lead: $json.lead, workflowExecutionId: $execution.id } }];
